#[test]
fn w330_schema_plan_capture() {
    let workspace = tempfile::tempdir().unwrap();
    for n in [0, 1, 20, 64] {
        let mut exports = serde_json::Map::new();
        let mut config_by_id = serde_json::Map::new();
        for i in 0..n {
            let id = format!("w330_binding_{i}");
            exports.insert(id.clone(), json!({"description": "description".repeat(4)}));
            config_by_id.insert(id, json!({"payload": "x".repeat(256), "flags": ["a", "b"]}));
        }
        let config: AppConfig = serde_json::from_value(if n==0 {json!({})} else {json!({
            "components": {"w330": {
                "command": "unused",
                "exports": {"model": exports}
            }},
            "module_config": {"model": config_by_id}
        })}).unwrap();
        let catalog = ModuleCatalog::from_config(&config).unwrap();
        assert_eq!(catalog.config_exports.len(), n);
        let source = std::hint::black_box(catalog.config_exports);
        let (captured, counts) = crate::w330_alloc::measure(|| std::hint::black_box(source.clone()));
        assert_eq!(captured.len(), n);
        for (a,b) in source.iter().zip(captured.iter()) {
            assert_eq!(a.component_id(), b.component_id());
            assert_eq!(a.binding(), b.binding());
            assert_eq!(a.description(), b.description());
            let value = &a.binding().module_config;
            assert!(value.to_string().contains(&"x".repeat(256)), "{value}");
        }
        let (_, setup) = crate::w330_alloc::measure(|| std::hint::black_box(Vec::<crate::process_adapters::ProcessExportConfig>::new()));
        println!("CAPTURE {n} {} {} SETUP {} {}", counts.calls, counts.bytes, setup.calls, setup.bytes);
    }
}

